let kp = MlDsa65::key_gen_internal(&ml_dsa::B32::from(*seed));
Ok((kp.signing_key().clone(), kp.verifying_key().clone()))
Ok(MlKem768::generate_deterministic(&d, &z))
let (ct, ss) = pk.encapsulate(&mut rand::thread_rng()).map_err(|()| ..)?;
